public class Ex02TraversalPerf {
    // Use "pointer hops" instead of System.nanoTime(): the conclusion is
    // machine-independent and fully reproducible.
    static class Node { int val; Node next; Node(int v) { val = v; } }

    static class SinglyLinkedList {
        Node head, tail;
        int size;
        void add(int v) {
            Node nd = new Node(v);
            if (head == null) head = nd; else tail.next = nd;
            tail = nd; size++;
        }
        int get(int i) {
            Node p = head;
            for (int k = 0; k < i; k++) p = p.next;   // i times pointer hops
            return p.val;
        }
    }

    public static void main(String[] args) {
        final int n = 50000;
        int[] arr = new int[n];
        SinglyLinkedList ll = new SinglyLinkedList();
        for (int i = 0; i < n; i++) { arr[i] = i; ll.add(i); }

        int mid = n / 2;
        System.out.println("n=" + n);
        System.out.println("array       get(" + mid + ") = " + arr[mid] + "   array lookups = 1");
        System.out.println("linked-list get(" + mid + ") = " + ll.get(mid)
                + "   pointer hops = " + mid);
        System.out.println("conclusion: O(1) array access beats O(n) list access = " + (mid > 1));
    }
}
